use std::{fs,path::Path};
fn names(s:&str)->Result<Vec<String>,String>{let mut v=vec![];for l in s.lines().filter(|l|l.starts_with('\'')){let(n,a)=l.strip_prefix('\'').unwrap().split_once("' ").ok_or("format")?;if a!="does not depend on any axioms"{let ax=a.strip_prefix("depends on axioms: [").and_then(|x|x.strip_suffix(']')).ok_or("axiom format")?;if !ax.split(", ").all(|x|["propext","Classical.choice","Quot.sound"].contains(&x)){return Err("forbidden".into())}}v.push(n.to_owned())}Ok(v)}
fn main(){let p=std::env::args().nth(1).unwrap();let p=Path::new(&p);for m in ["FallbackWordExact","FallbackWordChain","FallbackWordNumerator","FallbackWordNormal","FallbackWordDivisions","FallbackWordControls","FallbackWordReadback"]{assert_eq!(fs::read_to_string(p.join(format!("{m}.exit"))).unwrap().trim(),"0")};assert_eq!(fs::read_to_string(p.join("ExpectedFailure.exit")).unwrap().trim(),"1");let s=fs::read_to_string(p.join("FallbackWordReadback.stdout")).unwrap();let expected:Vec<_>=include_str!("inventory.txt").lines().collect();assert_eq!(expected.len(),17);assert_eq!(names(&s).unwrap(),expected);assert!(names("'Bad' depends on axioms: [sorryAx]").is_err());assert_ne!(names("").unwrap(),expected);assert_ne!(names(&s.replacen("exact_total","wrong",1)).unwrap(),expected);println!("{{\"accepted\":true,\"fresh_modules\":7,\"main_declarations\":11,\"producer_controls\":6,\"named_readbacks\":17,\"false_native_exit\":1,\"checker_controls\":3,\"independent_review\":\"pending\",\"scientific_execution\":false}}");}
